import{_ as a,o as n,c as t,a3 as e}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"CognitiveDrone: A VLA Model and Evaluation Benchmark for Real-Time Cognitive Task Solving and Reasoning in UAVs","description":"","frontmatter":{"title":"CognitiveDrone: A VLA Model and Evaluation Benchmark for Real-Time Cognitive Task Solving and Reasoning in UAVs","arxiv":"2503.01378","date":"2025-03-03","authors":"Artem Lykov, Valerii Serpiva, Muhammad Haris Khan, Oleg Sautenkov, Artyom Myshlyaev, Grik Tadevosyan, Yasheerah Yaqoot, Dzmitry Tsetserukou","categories":"cs.RO","topics":"无人机, 视觉语言动作模型, 认知基准","outline":[2,2]},"headers":[],"relativePath":"papers/2503.01378.md","filePath":"papers/2503.01378.md","lastUpdated":null}'),p={name:"papers/2503.01378.md"};function i(l,s,o,r,m,c){return n(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="cognitivedrone-a-vla-model-and-evaluation-benchmark-for-real-time-cognitive-task-solving-and-reasoning-in-uavs" tabindex="-1">CognitiveDrone: A VLA Model and Evaluation Benchmark for Real-Time Cognitive Task Solving and Reasoning in UAVs <a class="header-anchor" href="#cognitivedrone-a-vla-model-and-evaluation-benchmark-for-real-time-cognitive-task-solving-and-reasoning-in-uavs" aria-label="Permalink to &quot;CognitiveDrone: A VLA Model and Evaluation Benchmark for Real-Time Cognitive Task Solving and Reasoning in UAVs&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.01378" target="_blank" rel="noreferrer">2503.01378</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-03</td></tr><tr><td><strong>作者</strong></td><td>Artem Lykov, Valerii Serpiva, Muhammad Haris Khan, Oleg Sautenkov, Artyom Myshlyaev, Grik Tadevosyan, Yasheerah Yaqoot, Dzmitry Tsetserukou</td></tr><tr><td><strong>分类</strong></td><td>cs.RO</td></tr><tr><td><strong>一句话</strong></td><td>把 OpenVLA-7B 在 8062 条仿真飞行轨迹上微调成输出 4D 速度指令的无人机 VLA，再外挂一个 2 Hz 的 VLM 把复杂指令改写成简单指令喂给 10 Hz 的控制模型，并配套发布首个无人机认知任务基准 CognitiveDroneBench。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 模型在机械臂上已经形成完整的生态：RT-1/RT-2/RT-X 给出范式，OpenVLA 给出可微调的开源底座，LIBERO 给出标准化评测。无人机侧的情况截然不同——现有工作要么做规划与轨迹生成，要么做视觉语言导航，评测基本局限于竞速与基础导航，几乎没有任何基准去衡量&quot;无人机在飞行途中做出正确判断&quot;这件事。</p><p>本文要解决的是评测缺口与能力缺口的组合。所谓认知任务，指的是无人机在穿门时必须先解一个题才知道该穿哪一扇门：识别照片上是哪个人物、辨认门上的符号与 logo、或者做一次逻辑推理（&quot;飞到写着某道算术题答案的那扇门&quot;、&quot;飞到带甜味饮料标志的门&quot;）。这类任务的关键在于，飞行能力与判断能力是<strong>解耦但串联</strong>的——飞得再稳，选错门就是零分；判断再对，飞不过去也是零分。传统竞速指标完全测不出前者，而这恰恰是 UAV 走向实际任务（搜救中识别目标人物、巡检中辨认设备标识）时的核心能力。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>机械臂那一侧的经验不能直接搬。PaLM-E、RT-1/RT-2/RT-X 与 OpenVLA、MiniVLA、Octo 建立了&quot;多模态输入直接出控制信号&quot;的范式，LIBERO 把评测标准化，但这些都建立在静止相机、准静态、7 维末端动作的设定上。无人机的相机随机体运动、动作是四维速度、任务是穿越而非抓取，评测协议无法照搬。</p><p>无人机侧已有的工作分成两类。一类是 LLM/transformer 驱动的规划与导航：AerialVLN、Aerial Vision-and-Dialog Navigation、EmbodiedCity、OpenUAV、以及 SwarmGPT/FlockGPT 这样的集群控制。它们的共同结构是&quot;语言模型出高层指令，另有模块执行&quot;，因此语言理解与控制之间隔着一层人工设计的接口，既限制了实时性，也让&quot;模型是否真的理解了任务&quot;无法在闭环里被度量。另一类是同组早先的 <a href="/notes/papers/2503.02572">RaceVLA</a>，它第一次把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.044em;">z</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mclose">)</span></span></span></span> 四维控制信号做成端到端 VLA，但其数据与评测全在竞速场景，从未面对需要判断的任务。</p><p>论文给出的判断是：缺口不是&quot;没人做过 UAV 的 VLA&quot;，而是<strong>没有任何基准能把&quot;飞行能力&quot;与&quot;认知能力&quot;分开度量</strong>。在这个基准出现之前，任何关于&quot;无人机会不会推理&quot;的说法都无法证伪。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>2025 年初有几个既成观察。第一，OpenVLA 的微调门槛已经很低：RLDS 数据格式 + LoRA rank-32，几千步梯度就能把它改造成新本体的策略——这意味着&quot;再造一个 VLA&quot;不是研究工作量的大头，造数据与造基准才是。第二，DeepSeek-R1 与 o1 系列展示了&quot;把推理从反应式控制里拆出来&quot;能显著提升难题正确率；机器人侧 Figure 的 Helix 已经把这条思路落成 System 1/System 2 双频架构（7B VLM 慢思考 + 80M 视觉运动策略快执行），CognitiveOS 也做了模块分离。第三，同组自己的 RaceVLA 已经证明 7B VLA 能实时飞，但它面对需要判断的指令时表现如何，无人知道。</p><p>顺着走下去，最自然的实验是：先造一批&quot;必须解题才能选对门&quot;的仿真轨迹，微调出一个会飞也见过认知任务的 VLA；然后拿 RaceVLA（只会飞、没见过认知数据）作为对照，看差距有多大；再按 Helix 的分频思路挂一个 VLM 在前面，看把复杂指令改写成简单指令能补回多少。三个模型正好构成一条从&quot;只会飞&quot;到&quot;会飞会判断&quot;到&quot;会飞会判断还会先想一步&quot;的阶梯。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>一个端到端 VLA 的容量被两件事同时占用：把像素映射成平滑的连续控制，以及把语言指令解析成正确的目标。前者需要高频、需要贴近物理，后者需要慢、需要世界知识。把两者压在同一个 7B 模型的同一次前向里，训练信号会被飞行动力学主导，语言理解退化成近似随机的选择。解法不是把模型做大，而是把&quot;想清楚要去哪扇门&quot;这一步剥出来，交给一个跑在 2 Hz 的独立 VLM，让它把&quot;飞到写着 3+4 答案的门&quot;重写成&quot;飞到写着 7 的门&quot;，控制模型于是只需处理它擅长的那类简单指令。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 Reasoning 类的一个样本为例：&quot;导航到标有某道算术题答案的门&quot;。</p><ul><li><strong>仿真与数据</strong>：Gazebo + ArduPilot Gazebo 插件 + SITL ArduPilot，无人机由速度设定点控制，与真机运行 ArduPilot 固件的接口一致。门与标签用 <code>.sdf</code> + <code>.dae</code> 描述，任务由 JSON 定义（题面、选项、正确答案、门的尺寸/形状/颜色），ROS-Gazebo 插件动态生成物体。采集时相机无人机在初始点附近随机化位姿，沿样条轨迹飞向指定门的中心，每步记录 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">256</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">256</span></span></span></span> 的 RealSense 图像与施加的动作。共 8062 条连续轨迹，分 Human Recognition / Symbol Understanding / Reasoning 三类，按类别均衡划分训练集与测试集。</li><li><strong>控制模型</strong>：OpenVLA-7B 底座，数据整理成 RLDS 格式，LoRA rank-32 微调，batch 64、lr <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span>、4000 步、关闭图像增强，4 张 A100，每 500 步评估一次。输出为 4D 动作 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.044em;">z</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mclose">)</span></span></span></span>，运行在 10 Hz。</li><li><strong>推理模块（R1 变体）</strong>：外挂一个基于 Qwen2.5-VL 的 7B VLM，输入任务指令与视觉，输出被简化/消歧后的指令再送给 VLA。因 token 数更多，它运行在约 2 Hz；两个 7B 模型共存使显存需求从约 10 GB 翻倍到约 20 GB。</li><li><strong>评测</strong>：CognitiveDroneBench 用测试集样本在仿真中生成一条含多个连续门的赛道，每一段给一张 FPV 图与一句任务指令，穿过正确的门得 1 分，按类别用可得满分归一化。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。全文的量化部分只有动作向量的维度定义 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">y</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.044em;">z</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mclose">)</span></span></span></span>、训练超参与评测分数的归一化（累计得分除以理论满分），没有提出任何新的目标函数、约束或收敛性论证；LoRA、RLDS、OpenVLA 的训练目标均沿用原文。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：只会飞的模型在认知任务上有多差？</strong> RaceVLA 在三类任务上分别是 Reasoning 36.2%、Human Recognition 23.1%、Symbol Understanding 34.6%，总均值 31.3%。论文对此的描述是&quot;能可靠地穿过门，但选门时近乎随机&quot;——这句自评很重要，它同时说明了该基准把飞行与判断解耦成功了，也说明这个对照组基本等价于一个随机基线。</p><p><strong>问题二：见过认知数据的 VLA 能补回多少？</strong> CognitiveDrone 得到 Reasoning 70.7%、Human Recognition 45.2%、Symbol Understanding 57.7%，总均值 59.6%。有意思的是三类的排序：Reasoning 最高而 Human Recognition 最低，与直觉相反（推理通常被认为比识别难）。论文没有讨论这个反转，可以推断的原因是 Reasoning 类的题面往往把答案映射到一个数字或一个显著 logo 上，视觉判别反而更容易；而人物识别要求区分外貌特征相近的多张照片，是纯粹的细粒度视觉问题。这属于基于证据的推断，论文未明确声明。</p><p><strong>问题三：外挂推理模块的增益在哪？</strong> CognitiveDrone-R1 得到 Reasoning 75.9%、Human Recognition 76.79%、Symbol Understanding 78.9%，总均值 77.2%。逐项看增益极不均匀：Reasoning 只涨 5.2 个百分点，Human Recognition 涨 31.6 个百分点，Symbol Understanding 涨 21.2 个百分点。这与&quot;推理模块用来解题&quot;的叙事恰好相反——增益最小的正是 Reasoning 这一类。更自洽的解释是，Qwen2.5-VL 的贡献主要来自它自身更强的视觉识别能力（认人、认符号），而不是来自&quot;把复杂指令简化&quot;这一机制。论文把这一现象归结为&quot;整体决策能力提升&quot;，未做进一步拆解。</p><p>注意口径：摘要里&quot;improvements of up to 30%&quot;与正文的&quot;约 6%/31%/21%&quot;混用了百分点与相对提升的表述，其中 6% 对应 70.7→75.9（5.2 个百分点），应按百分点理解。加上推理模块后三类分数落在 75.9–78.9 的窄带里，方差明显收窄。</p><p><strong>缺失的实验</strong>：全文没有真机飞行、没有推理模块的消融（例如换成更小的 VLM、或只做指令改写不看图）、没有延迟与端到端控制频率的实测、也没有与&quot;直接用 Qwen2.5-VL 选门 + 传统控制器飞行&quot;这一显然基线的对比。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：本文给无人机补上了 VLA 生态里缺失的两块——一个见过认知任务的 7B 控制模型，与第一个把飞行能力与判断能力解耦度量的基准 CognitiveDroneBench。数据是 8062 条 Gazebo 仿真轨迹，分人物识别、符号理解、推理三类，训练用 LoRA rank-32 微调 OpenVLA-7B。竞速导向的 RaceVLA 总分 31.3%（作者自评为近乎随机），加入认知数据后升到 59.6%，再外挂一个 2 Hz 的 Qwen2.5-VL 推理模块升到 77.2%。推理模块的增益极不均匀：人物识别 +31.6 个百分点，而它本应最擅长的推理类只有 +5.2。全部结果均在仿真中取得，无真机验证、无组件消融。</p><p><strong>3 句话版</strong>：把&quot;飞&quot;与&quot;判断&quot;拆成两个频率不同的模型，是当前 7B 规模下让无人机 VLA 同时具备两种能力的可行工程解。配套基准的价值大于模型本身，因为它第一次让&quot;无人机是否理解了指令&quot;变得可证伪。但增益的逐类分布提示真正起作用的是外挂模型更强的视觉识别，而非指令简化机制。</p><p><strong>1 句话版</strong>：给无人机 VLA 外挂一个慢速 VLM，总分从 59.6% 到 77.2%，但增益主要落在识别而不是推理上。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>CognitiveDroneBench 的分数衡量的是认知能力，而不是对同一条数据生成流水线的拟合程度</strong>。基准的测试样本与训练样本来自同一个 8062 条轨迹的数据集，只是按类别均衡划分；门的 <code>.sdf</code>/<code>.dae</code> 模型、题面 JSON 的生成方式、样条轨迹的生成器、随机化初始位姿的分布全部相同。这意味着测试集与训练集的差异只是&quot;具体哪一道题、哪一张人脸&quot;，而不是&quot;新的场景、新的题型、新的视觉条件&quot;。</p><p>一旦这条不成立，59.6% 与 77.2% 度量的就主要是同分布内插能力。三个佐证使这个担忧不是空穴来风：其一，唯一的对照 RaceVLA 从未见过这个分布，它的 31.3% 与&quot;近乎随机&quot;的自评一致，说明整张表的动态范围其实是&quot;见过这个分布&quot;与&quot;没见过&quot;之间的差距；其二，加了推理模块后三类分数收敛到 75.9–78.9 的窄带，看起来更像是触到了某个流水线上限；其三，论文完全没有报告随机基线是多少——每一段有几扇门、随机猜的期望得分是多少，全文未给。若赛道每段是 3 选 1，随机基线就是 33.3%，那么 RaceVLA 的 31.3% 恰好等于随机，整篇论文实际上只有一个有意义的对照组，而它是个随机基线。</p><p>论文为这条假设提供的证据是：训练/测试按类别均衡划分。缺的是：跨场景留出（新的门材质、新的光照、新的题型模板）、随机基线数值、以及任何真机或跨仿真器的验证。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现整套系统，一周内可做的最小验证聚焦一个问题：<strong>推理模块的增益到底来自&quot;指令简化&quot;还是&quot;更强的视觉编码器&quot;？</strong></p><ol><li>直接使用作者开源的仿真环境、数据集与模型权重（论文声明全部开源）。</li><li>构造四个 arm：(a) CognitiveDrone 基础版；(b) CognitiveDrone-R1 原样；(c) R1 但把 Qwen2.5-VL 的输入去掉图像、只给文本指令做改写（若增益来自纯语言的指令简化，此 arm 应保住大部分增益）；(d) R1 但用一个<strong>只做识别不做简化</strong>的模块——让 VLM 直接回答&quot;画面里三扇门上分别是什么&quot;，把答案原样拼进 prompt 而不改写指令。</li><li>度量三类任务分数，并额外记录随机基线（用一个恒定输出前向速度、门选择随机的控制器跑同一条赛道）。</li></ol><p>判据：若 (c) 只保住很小一部分增益而 (d) 几乎保住全部，则&quot;指令简化&quot;这一机制被证伪，正确的叙事应改为&quot;外挂一个视觉更强的模型来做感知&quot;；若 (c) 与 (b) 接近，则原叙事成立。这个实验同时补上了论文缺失的随机基线。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释</strong>：整张表可以在不假设任何&quot;认知能力&quot;的前提下被解释。RaceVLA 的动作分布来自竞速数据（连续高速穿门），CognitiveDrone 的动作分布来自本数据集的样条轨迹（从随机初始点飞向指定门中心）。两者的动作分布本身就不同。因此 31.3%→59.6% 这一跳，可能主要反映的是<strong>动作分布匹配</strong>而非语义理解：RaceVLA 输出的速度指令在这条赛道的几何下更容易偏离目标门，与它&quot;看懂没看懂&quot;无关。要区分这两种解释，需要一个关键对照：把 CognitiveDrone 在<strong>打乱标签</strong>的数据上训练（视觉与轨迹保持不变，但题面与正确门的对应关系随机置换）。若这个&quot;语义被破坏&quot;的模型仍能拿到明显高于 31.3% 的分数，那么 RaceVLA 与 CognitiveDrone 的差距就主要是分布匹配，而不是认知。这个对照论文没有做，而它的成本极低。</p><p><strong>可预测的失败条件</strong>：本方法的双模型结构假设推理模块的输出能被控制模型正确执行。但推理模块以约 2 Hz 运行，而无人机以 10 Hz 控制——两次改写之间有 5 个控制步。若无人机在这段时间里飞到了另一扇门的视野中心，控制模型收到的是一条<strong>基于 5 步之前画面</strong>得出的简化指令。在门间距小、飞行速度高的赛道上，这种时序错配会系统性地导致&quot;穿了正确指令对应的门的邻居&quot;。论文的赛道与速度参数未给出，因此无法判断当前设置是否已经触及这个边界；一个直接的攻击实验是把飞行速度提高 2–3 倍并观察 R1 相对基础版的优势是否反转。</p><p><strong>第三点</strong>：显存从 10 GB 翻倍到 20 GB，两个 7B 模型的部署对机载算力是硬约束，而论文只说训练时&quot;保持了在 UAV 硬件上的实时可部署性&quot;，没有给出任何机载推理的延迟数字，也未说明评测时模型跑在哪里。在同组的 RaceVLA 里，7B 模型是跑在地面 RTX 4090 上、通过 Flask API 与无人机通信、总频率 4 Hz——若本文也是同样的离机部署，那么&quot;real-time&quot;这一措辞需要显著限定。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：本文的双频结构是静态的——推理模块无论任务难易都以固定 2 Hz 运行，控制模块无论指令是否被简化都以同样方式执行。这既浪费算力（简单指令不需要改写），又在难题上给得不够（一次改写就定死，没有纠错机会）。更关键的是，两个模块之间的接口是一条自然语言字符串，控制模型无从知道这条指令的可信度有多高。</p><p><strong>(b) 可借鉴的相邻工具</strong>：<strong>anytime / 中断式规划</strong>（anytime algorithms 与 interruptible planning）在经典 AI 规划里已经把&quot;随时可以给出当前最优解、给更多时间就更优&quot;形式化了，配套的元推理（metareasoning）框架专门回答&quot;再想一步的边际收益是否超过延迟代价&quot;。</p><p><strong>(c) 新 framing 与第一个实验</strong>：把慢-快分频从固定频率改写成<strong>由不确定性触发的中断</strong>。推理模块输出的不再是一条指令，而是&quot;简化后的指令 + 一个置信度&quot;；控制模型在置信度低时降速盘旋以争取时间、在置信度高时全速穿越；推理模块只在置信度低或视觉场景发生显著变化时才被重新调用。这把&quot;两个模型的频率比&quot;从一个超参数变成一个由任务难度自适应决定的量，也让&quot;想更久是否更准&quot;第一次可测。第一个实验：在 CognitiveDroneBench 上加入一个<strong>速度维度</strong>的评分（总分 = 认知正确率 × 完赛时间的某个折扣），对比固定 2 Hz、固定 0.5 Hz、以及不确定性触发三种调度；同时用 § 11 的高速赛道检验中断式调度是否消除了时序错配导致的&quot;穿邻门&quot;失败。若成立，无人机 VLA 的评测就从&quot;分数&quot;升级为&quot;分数-延迟前沿&quot;，这比继续把模型做大更贴近真实的机载约束。</p>',46)])])}const u=a(p,[["render",i]]);export{h as __pageData,u as default};
